use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct State {
    ready: bool,
}

struct Shared {
    m: Mutex<State>,
    cv: Condvar,
}

fn waiter(shared: Arc<Shared>) {
    let mut state = shared.m.lock().unwrap();

    while !state.ready {
        state = shared.cv.wait(state).unwrap();
    }
}

fn notifier(shared: Arc<Shared>) {
    let mut state = shared.m.lock().unwrap();
    state.ready = true;
    shared.cv.notify_one();
    drop(state);
}

fn main() {
    let shared = Arc::new(Shared {
        m: Mutex::new(State { ready: false }),
        cv: Condvar::new(),
    });

    let waiter_handle = {
        let shared = Arc::clone(&shared);
        thread::spawn(move || waiter(shared))
    };

    let notifier_handle = {
        let shared = Arc::clone(&shared);
        thread::spawn(move || notifier(shared))
    };

    waiter_handle.join().unwrap();
    notifier_handle.join().unwrap();

    let state = shared.m.lock().unwrap();
    println!("DONE ready={}", state.ready);
}
